from collections import deque

def fill_adjacent(grid, target_color):
    """Fill all cells of a certain type adjacent to the target color"""
    result = [row[:] for row in grid]
    # Find all non-target cells
    non_target = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != target_color:
                non_target.add((r, c))

    # Check which ones are adjacent to target
    results = set()
    for r, c in non_target:
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == target_color:
                results.add((r, c))
                break

    for r, c in results:
        result[r][c] = target_color
    return result

